package io.knowledgebrain.integration;
import java.util.*;import java.time.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.apache.kafka.clients.consumer.*;import io.knowledgebrain.contracts.integration.github.v1.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_INTEGRATION_KAFKA_BOOTSTRAP",matches=".+")
class GitHubKafkaIntegrationTest {
 @Test void sourceTransactionBytesAndSchemaHeadersReachBothTopicsOnlyThroughConnect()throws Exception{var f=new GitHubStoreIntegrationTest();f.setup();var repo=f.connect();var sync=f.store.sync(f.space,repo.repositoryId(),f.actor,f.key(),1,f.batch(),f.trace);f.store.disconnect(f.space,repo.repositoryId(),f.actor,2,f.trace);var expected=new HashMap<String,byte[]>();f.sql.query("SELECT id,payload FROM outbox_event WHERE aggregateid IN (SELECT repository_id FROM github_repository WHERE space_id=? UNION SELECT commit_id FROM github_commit WHERE space_id=?)",(rs,n)->Map.entry(rs.getObject(1,UUID.class).toString(),rs.getBytes(2)),f.space,f.space).forEach(e->expected.put(e.getKey(),e.getValue()));assertEquals(5,expected.size());var p=new Properties();p.put("bootstrap.servers",System.getenv("BRAIN_TEST_INTEGRATION_KAFKA_BOOTSTRAP"));p.put("group.id","integration-validation-"+f.ids.next());p.put("enable.auto.commit","false");p.put("auto.offset.reset","earliest");p.put("key.deserializer","org.apache.kafka.common.serialization.StringDeserializer");p.put("value.deserializer","org.apache.kafka.common.serialization.ByteArrayDeserializer");p.put("security.protocol","SSL");p.put("ssl.endpoint.identification.algorithm","HTTPS");p.put("ssl.truststore.type","PEM");p.put("ssl.truststore.certificates",Files.readString(Path.of("/integration-kafka-test/ca.crt")));p.put("ssl.keystore.type","PEM");p.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/integration-kafka-test/user.crt")));p.put("ssl.keystore.key",Files.readString(Path.of("/integration-kafka-test/user.key")));try(var c=new KafkaConsumer<String,byte[]>(p)){c.subscribe(List.of("integration.github-repository.v1","integration.github-commit.v1"));var found=new HashSet<String>();var versions=new ArrayList<Long>();long deadline=System.nanoTime()+Duration.ofSeconds(90).toNanos();while(found.size()<expected.size()&&System.nanoTime()<deadline)for(var row:c.poll(Duration.ofSeconds(1))){var e=GitHubEventEnvelopeV1.parseFrom(row.value());if(!expected.containsKey(e.getEventId()))continue;assertArrayEquals(expected.get(e.getEventId()),row.value());assertEquals(e.getAggregateId(),row.key());assertEquals(f.space.toString(),e.getSpaceId());assertEquals(f.actor.toString(),e.getActorId());assertEquals(f.trace,e.getTraceId());assertEquals("integration-service",e.getProducer());String artifact;if(e.getAggregateType().equals("GitHubRepository")){var snapshot=GitHubRepositorySnapshotV1.parseFrom(e.getPayload());assertEquals(repo.repositoryId().toString(),snapshot.getRepositoryId());artifact="github-repository-events";if(found.add(e.getEventId()))versions.add(snapshot.getVersion());}else{var snapshot=GitHubCommitImportedV1.parseFrom(e.getPayload());assertEquals("PRIVATE",snapshot.getVisibility());assertEquals("PUBLIC",snapshot.getSourceVisibility());assertEquals(1,snapshot.getVersion());artifact="github-commit-events";found.add(e.getEventId());}for(var entry:Map.of("id",e.getEventId(),"trace_id",f.trace,"schema_group","integration","schema_artifact",artifact,"schema_version","1").entrySet())assertEquals(entry.getValue(),new String(row.headers().lastHeader(entry.getKey()).value(),StandardCharsets.UTF_8));}assertEquals(expected.keySet(),found);assertEquals(List.of(1L,2L,3L),versions);}}
}
